PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS portfolio_datasets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','ACTIVE','ARCHIVED','REJECTED')),filename TEXT NOT NULL,file_hash TEXT NOT NULL,parser_version TEXT NOT NULL,row_count INTEGER NOT NULL,validation_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT(datetime('now')),activated_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(user_id,revision));
CREATE TABLE IF NOT EXISTS portfolio_state(user_id TEXT PRIMARY KEY,active_dataset_id TEXT,cloud_revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(active_dataset_id) REFERENCES portfolio_datasets(id));
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL,user_id TEXT NOT NULL,source_row_number INTEGER NOT NULL,trade_date TEXT NOT NULL,transaction_type TEXT NOT NULL,ticker TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 0,price REAL NOT NULL DEFAULT 0,amount_foreign REAL NOT NULL DEFAULT 0,row_hash TEXT NOT NULL,FOREIGN KEY(dataset_id) REFERENCES portfolio_datasets(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),UNIQUE(dataset_id,source_row_number));
CREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_dataset_per_user ON portfolio_datasets(user_id) WHERE status='ACTIVE';
CREATE INDEX IF NOT EXISTS idx_transactions_dataset_date ON transactions(dataset_id,trade_date,source_row_number);
